window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"HDVIIPEIKcQ","speaker":"Hussain Mohamed Latheef","role":"Vice President","country":"Maldives","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=HDVIIPEIKcQ","date":"20260925","title":"🇲🇻 Maldives - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":965,"words":1756,"counts":{"claims":22,"promises":2,"attacks":2},"topics":[{"topic":"Palestine statehood","share":0.1332,"seconds":128},{"topic":"Maldives development","share":0.0746,"seconds":72},{"topic":"AI opportunities","share":0.0737,"seconds":71},{"topic":"Israel-Gaza","share":0.0693,"seconds":67},{"topic":"Maldives sovereignty","share":0.0681,"seconds":66},{"topic":"Maldives diplomacy","share":0.0667,"seconds":64},{"topic":"Maldives economy","share":0.0666,"seconds":64},{"topic":"Small state rights","share":0.0664,"seconds":64},{"topic":"AI governance","share":0.0662,"seconds":64},{"topic":"Maldives climate","share":0.0635,"seconds":61},{"topic":"UN leadership","share":0.0634,"seconds":61},{"topic":"Hormuz closure","share":0.0632,"seconds":61},{"topic":"UNGA session","share":0.0629,"seconds":61},{"topic":"UNSC reform","share":0.0623,"seconds":60}],"timeline":[[1,62,null],[63,123,"UNGA session"],[127,192,"Maldives sovereignty"],[196,257,"Hormuz closure"],[260,323,"Palestine statehood"],[325,392,"Israel-Gaza"],[397,462,"Palestine statehood"],[465,527,"Maldives climate"],[530,602,"Maldives development"],[603,668,"Maldives economy"],[670,741,"AI opportunities"],[743,807,"AI governance"],[808,868,"UNSC reform"],[877,941,"Maldives diplomacy"],[944,1005,"UN leadership"],[1007,1071,"Small state rights"],[1073,1100,null]],"stances":{"UNGA session":"Hussain Mohamed Latheef expresses full support for the new president of the 81st UNGA and emphasizes that trust in the UN must be restored through tangible delivery rather than words.","Maldives sovereignty":"Hussain Mohamed Latheef asserts that the Maldives led a UN resolution affirming small states' sovereignty and argues that modern threats to sovereignty are non-territorial, requiring all states to have the freedom to shape their own future.","Hormuz closure":"The speaker condemns the closure of the Strait of Hormuz and asserts that regional conflicts impact the Maldives through economic channels.","Palestine statehood":"Hussain Mohamed Latheef asserts that the right to a sovereign future is denied in Palestine and argues that security cannot be built by exporting violence or violating others' sovereignty.","Israel-Gaza":"Hussain Mohamed Latheef asserts that international law must apply equally to all states without exception and demands an immediate end to Israel's actions in Gaza.","Maldives climate":"Hussain Mohamed Latheef states that climate change is a critical issue for the Maldives affecting national security and sovereignty, and calls for immediate financial support to build resilience.","Maldives development":"Hussain Mohamed Latheef states that the Maldives is pursuing a goal to become a developed country by 2040 through specific economic and social strategies.","Maldives economy":"Hussain Mohamed Latheef argues that the international financial system must be reformed to expand choices for developing nations and that Maldives has joined the BROWS platform to secure a voice in shaping this system.","AI opportunities":"Hussain Mohamed Latheef states that artificial intelligence offers significant opportunities for small states to close distance, overcome scale, and improve public services, but emphasizes these benefits must be shared.","AI governance":"Hussain Mohamed Latheef argues that every country must have a voice in shaping global AI roles and that the digital future should not create new forms of dependence.","UNSC reform":"Hussain Mohamed Latheef argues that the UN Security Council requires expansion to reflect the modern world, including new permanent and non-permanent seats for Africa, a rotating seat mechanism, and the abolition of the veto power.","Maldives diplomacy":"Hussain Mohamed Latheef states that the Maldives is seeking election to multiple UN bodies and argues that small states must be decision makers rather than decision takers.","UN leadership":"Hussain Mohamed Latheef calls for a transparent, merit-based selection process for the next UN Secretary-General that includes women and ensures representation for all member states.","Small state rights":"Hussain Mohamed Latheef argues that international cooperation must be measured by its ability to protect the freedom of small states to choose their own future and reduce dependence on external powers."},"claims":[{"t":111,"quote":"37 years ago, the mods asked this assembly to face a simple truth. That small state can be highly vulnerable to external threats and acts of influence.","topic":"UNGA session","kind":"fact"},{"t":128,"quote":"this assembly adopted resolution 4451, an initiative led by the Maldives, affirming the importance of protecting the sovereignty and territorial integrity of small states.","topic":"Maldives sovereignty","kind":"fact"},{"t":232,"quote":"Interruption to maritime traffic through the state of Hormones raises fuel prices. It affects food supplies and air The consequences of these are felt across tourism and public finances in the Maldives.","topic":"Hormuz closure","kind":"fact"},{"t":260,"quote":"The modest father condemns the attack attacks on Saudi Arabia, United Arab Emirates, Bahrain, Gatar, Kuwait, Oman and Jordan.","topic":"Palestine statehood","kind":"fact"},{"t":306,"quote":"Its military attacks across the region have violated the sovereignty of other","topic":"Palestine statehood","kind":"fact"},{"t":349,"quote":"The problem is not a lack of law. The rules are clear.","topic":"Israel-Gaza","kind":"fact"},{"t":363,"quote":"International law cannot bind the weak and bend for the powerful.","topic":"Israel-Gaza","kind":"fact"},{"t":430,"quote":"recognition of independent and sovereign state of Palestine based on the pre967 borders with East Jerusalem as its","topic":"Palestine statehood","kind":"fact"},{"t":465,"quote":"For seeds like the Maldives, none is more consequential than climate change. For seeds, climate change is altering the very fiscal foundations of our Sea level rise is therefore not simply an environmental concern.","topic":"Maldives climate","kind":"fact"},{"t":492,"quote":"Rising seas may alter our shores, but they will not erase our statethood. They will not reduce our rights. They will not weaken our maritime entitlements. and they will not diminish our national","topic":"Maldives climate","kind":"fact"},{"t":582,"quote":"His Excellency President Dr. Muhammad Moizu has set a clear ambition. Furthermore is to become a developed country by 2040.","topic":"Maldives development","kind":"fact"},{"t":647,"quote":"Earlier this year, the mods joined other developing countries in launching the Brows platform.","topic":"Maldives economy","kind":"fact"},{"t":722,"quote":"Artificial intelligence offers significant opportunities for small states. AI can close distance. It can help overcome scale and it can put better health care, education and public services within","topic":"AI opportunities","kind":"fact"},{"t":743,"quote":"Every country must have a voice in shaping the global roles for AI.","topic":"AI governance","kind":"fact"},{"t":764,"quote":"The UN80 initiative is an opportunity to reduce duplication, improve accountability, and focus resources on But efficiency must not be measured simply by what we cut.","topic":"AI governance","kind":"fact"},{"t":835,"quote":"The security council cannot reflect the world of 1945 while deciding for the world of today.","topic":"UNSC reform","kind":"fact"},{"t":852,"quote":"Africa must receive the represent representation long denied to it","topic":"UNSC reform","kind":"fact"},{"t":900,"quote":"The molds will take its seat on the economic and social council for the 2027 to 2029 term.","topic":"Maldives diplomacy","kind":"fact"},{"t":908,"quote":"We are seeking election to the human rights council for the 2028 to 2030 term.","topic":"Maldives diplomacy","kind":"self_credit"},{"t":915,"quote":"And we seek the support of member states for a seat on the UN Security Council for the 2033 to 2034 term.","topic":"Maldives diplomacy","kind":"self_credit"},{"t":968,"quote":"For more than eight decades, every secretary general has been a man.","topic":"UN leadership","kind":"fact"},{"t":1054,"quote":"In 1989, the modest asked this assembly to protect small states from external","topic":"Small state rights","kind":"fact"}],"promises":[{"t":68,"quote":"You can count on the full support of the Maldives as you lead this assembly.","topic":"UNGA session","kind":"promise"},{"t":421,"quote":"The Morris will always stand with Palestinian people and their undeniable right for that future.","topic":"Palestine statehood","kind":"promise"}],"attacks":[{"t":374,"quote":"Israel's genocide in Gaza must end.","topic":"Israel-Gaza","target":"Israel"},{"t":377,"quote":"Israel's illegal occupation of Palestine and other Arab lands must end.","topic":"Israel-Gaza","target":"Israel"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"We shall now continue the general The assembly will hear an address by his excellency Hussein Muhammad Latif, Vice President of the Republic of Maldives. I request protocol to escort his excellency in and invite him to address the assembly. Rahman Rahim, Mr. President, Mr. Secretary General, excellencies, ladies and gentlemen, assalamu alalaykum. I congratulate you, Mr."},{"t":63,"topic":"UNGA session","text":"president on your election as president of the 81st You can count on the full support of the Maldives as you lead this assembly. I also thank former president of the general assembly high excellency Anelena Babuk for her leadership of the 80th This year's theme, restoring trust, managing transformation, a united nations that delivers for all, captures the task before us. Trust will not be restored by words alone. It will be restored by what this organization delivers for every country, large or small. 37 years ago, the mods asked this assembly to face a simple truth. That small state can be highly vulnerable to external threats and acts of influence."},{"t":127,"topic":"Maldives sovereignty","text":"In response, this assembly adopted resolution 4451, an initiative led by the Maldives, affirming the importance of protecting the sovereignty and territorial integrity of small states. That was true then and it is true even today. But the threats have evolved. Insecurity now travels through sea lanes, supply chains, financial markets, digital networks and new technologies. Today, sovereignty can be weakened without a single border being crossed. It can be undermined when external powers limit a state's freedom to This is why the Morris comes before this assembly with a clear message. Every state large or small must have the freedom and capacity to shape its own A sovereign future and that future begins with peace."},{"t":196,"topic":"Hormuz closure","text":"The Indian Ocean must remain peaceful. It must remain as a region where trade can flow and where states can prosper. Regional competition among major powers must not limit the choices of smaller Conflict does not have to reach our shores to affect us. In today's interconnected world, a crisis far away can quickly become a crisis at home. Interruption to maritime traffic through the state of Hormones raises fuel prices. It affects food supplies and air The consequences of these are felt across tourism and public finances in the Maldives. The mod therefore condemns the closure of the state of Hormuz. The state must remain open and safe."},{"t":260,"topic":"Palestine statehood","text":"The modest father condemns the attack attacks on Saudi Arabia, United Arab Emirates, Bahrain, Gatar, Kuwait, Oman and Jordan. The modus appreciates the diplomatic efforts of Oman, Pakistan and gut to deescalate the crisis and bring the parties to dialogue. The right to offer, the right to a sovereign future must belong to all. And nowhere is that right more brutally denied than in Palestine. Is genocide and war crimes against Palestinian continue and their actions are not confined to Gaza. Its military attacks across the region have violated the sovereignty of other Security cannot be built by exporting Nor can any country demand respect for its sovereignty while violating the sovereignty of others."},{"t":325,"topic":"Israel-Gaza","text":"No state should be shielded from accountability by its power or political But condemnation alone is not enough. Every member state must ask what have we done to end this violence. The United Nations must ask itself the same question. The problem is not a lack of law. The rules are clear. What is absent is equal International law cannot bind the weak and bend for the powerful. The same rules, the same standard, no exception. Israel's genocide in Gaza must end. Israel's illegal occupation of Palestine and other Arab lands must end. Illegal settlements must end. Humanitarian assistance must reach Palestinians safely, rapidly and at scale."},{"t":397,"topic":"Palestine statehood","text":"International courts and other and the resolution of this organization must be respected and implemented for the Palestinian people. A sovereign future means freedom, dignity, self-determination, and the right to live their security in their own state. The Morris will always stand with Palestinian people and their undeniable right for that future. This is why I reiterate our call for the recognition of independent and sovereign state of Palestine based on the pre967 borders with East Jerusalem as its And if this organization is restored trust and deliver for all, Palestine must become a full member of the United Conflict is not the only threat to sovereignty. Forces beyond our borders can also limit a state's freedom to shape its own future."},{"t":465,"topic":"Maldives climate","text":"For seeds like the Maldives, none is more consequential than climate change. For seeds, climate change is altering the very fiscal foundations of our Sea level rise is therefore not simply an environmental concern. It is a matter of national planning and national security. It is a matter of sovereignty. Let there be no doubt. Rising seas may alter our shores, but they will not erase our statethood. They will not reduce our rights. They will not weaken our maritime entitlements. and they will not diminish our national Our response must be to adapt, innovate and build. But resilience demands the means to act. That means finance must reach those who need it at the scale, at the speed, and on the terms needed to build resilience."},{"t":530,"topic":"Maldives development","text":"This is why COP 31 in Antholia must be a cope of delivery. Implementation must be the measure of We must we must move faster. We must speed up 2030 agenda and we must turn a bus into measurable progress for seeds. For island nations that progress cannot be separated from a healthy and sustainably managed ocean. Therefore, the first conference of the parties to the BG BBNG agreement must deliver from day one. Ultimately, global commitments matter only when they enable progress at home. His Excellency President Dr. Muhammad Moizu has set a clear ambition. Furthermore is to become a developed country by 2040. We are pursuing that goal by rising productivity, diversifying our economy, building resilient infrastructure, expanding renewable energy and investing in our people."},{"t":603,"topic":"Maldives economy","text":"Our future will be built by moldivians. But the international system can widen or narrow our choices. Technology transfer, resilient supply chains and accessible finance expand Techn technological dependence, external shocks and unsustainable debt limits it. This is why reform of the international financial architecture matters. We must implement the sea commitment and deliver on its promises on finance, debt and reform. Earlier this year, the mods joined other developing countries in launching the Brows platform. It must become a lasting mechanism that gives developing countries not just a place in the financial system but a voice in shaping it. But for seeds, greater agency also depends on progress at home."},{"t":670,"topic":"AI opportunities","text":"We must build our institutions, improve stability and attract responsible investment and meaningful partnerships. And these partnerships must build national capacity and support national Partnerships must solve national needs, strengthen what we have and leave us more capable than before. Our shared challenges can become a shared This is the spirit of President Dr. Muhammad Moiz's mold's first policy. Partnership built around respect, national interest and mutual and the same principle must guide the technological transformation before us. Artificial intelligence offers significant opportunities for small states. AI can close distance. It can help overcome scale and it can put better health care, education and public services within But these opportunities must be shared."},{"t":743,"topic":"AI governance","text":"Every country must have a voice in shaping the global roles for AI. The digital future should strengthen our ability to serve our people better, not create new forms of dependence. And as the world transform, so must the United Nations. The UN80 initiative is an opportunity to reduce duplication, improve accountability, and focus resources on But efficiency must not be measured simply by what we cut. It must be measured by what we deliver. And the United Nation must not retreat from the countries that need it most in the name of efficiency. Reform must preserve a meaningful UN presence on the ground particularly in The UN development system must respond to the needs of program countries and remain guided by relevant international The reform process must be member stateled."},{"t":808,"topic":"UNSC reform","text":"It must include must be inclusive and and transparent. This is how reform will restore trust by bring the United Nations closer to the people in the countries it serves. Reform must also confront one of this organization oldest weaknesses, unequal The security council cannot reflect the world of 1945 while deciding for the world of today. It must be expanded in both permanent and non-permanmanent categories. Seats must have a rotarian seat. Africa must receive the represent representation long denied to it and the veto must be abolished. After all, representation is not merely Who sits at the table shapes what the table sees."},{"t":877,"topic":"Maldives diplomacy","text":"Small states understand how closely climate, finance, trade, supply chains and security are connected. We also know that international law is our strongest safeguard against unequal power. That principle must remain at the heart of the international system. The molds will take its seat on the economic and social council for the 2027 to 2029 term. We are seeking election to the human rights council for the 2028 to 2030 term. And we seek the support of member states for a seat on the UN Security Council for the 2033 to 2034 term. We do so because small states must be decision makers, not decision takers. Representation matters not only within the bodies of this organization but also in its leadership."},{"t":944,"topic":"UN leadership","text":"As Secretary General Gutes approaches the end of a decade of service, the Mais thank him for his leadership and commitment to international cooperation. The process to choose his successor must be transparent and based on merit. It must draw from the full breath of talent available to this organization. For more than eight decades, every secretary general has been a man. It is time for woman to lead this A leader who will defend the charter without exception. Who can turn reform into delivery and who will listen to all member states including smallest. The task ahead is immense. The choice we make must meet it. So what should this assembly do? The modus proposes a simple test for a sovereign future."},{"t":1007,"topic":"Small state rights","text":"When we act on conflict, climate, finance, technology or institutional reform, let us ask does this decision expand a status freedom tools? Does it build national capacity and reduce dependence? Does it protect sovereignty and independence decision making? If the answer is no, we must change course and we must hold every state to the same Let this be the measure of n international cooperation. Not what we promise but what we make possible. This is the measure of a united nations that delivers for all. In 1989, the modest asked this assembly to protect small states from external Today, we ask it to protect something just as fundamental. Every state's freedom to choose choose its own future."},{"t":1073,"topic":null,"text":"A future chosen by its people. A future grounded in international law. a sovereign future for every state. I thank you. On behalf of the assembly, I wish to thank the vice president of the Republic of Maltics."}],"compare":[{"topic":"Israel–Palestine","share":0.2025,"mean":0.0516,"rank":9,"others":76},{"topic":"UN & its reform","share":0.1886,"mean":0.2048,"rank":100,"others":170},{"topic":"Artificial Intelligence","share":0.1398,"mean":0.05,"rank":20,"others":83},{"topic":"Maldives","share":0.1348,"mean":0.0,"rank":1,"others":0},{"topic":"Small states","share":0.0664,"mean":0.0021,"rank":5,"others":6},{"topic":"Strait of Hormuz","share":0.0632,"mean":0.0028,"rank":4,"others":5}]};
